    fileprivate static let handleMap = UniffiHandleMap<EngineListener>()

    typealias FfiType = UInt64
    typealias SwiftType = EngineListener

    public static func lift(_ handle: UInt64) throws -> EngineListener {
        if ((handle & 1) == 0) {
