    /**
     * Loads a database's stored stats once.
     */
    func ensureLoaded(database: ExplorerDatabase) 
    
    /**
     * The database's offline table is downloading: fetch nothing for it until
     * `coverage_table_download_ended`.
     */
    func expectCoverageTable(database: ExplorerDatabase) 
    
    /**
     * The position on screen.
     */
    func focus(epd: Epd, database: ExplorerDatabase, nowMs: Int64) 
    
    /**
     * Whether the database has an offline coverage table.
     */
    func hasCoverageTable(database: ExplorerDatabase)  -> Bool
    
    /**
     * The answer to a fetch (`response` None: no answer, e.g. offline).
     */
    func onResponse(fetch: Fetch, response: HttpResponse?, nowMs: Int64)  -> FetchOutcome
    
    /**
     * The requests to send now, and when to poll again. `token`: the Lichess token, if
     * signed in.
     */
    func poll(nowMs: Int64, token: String?)  -> Poll
    
    /**
     * Coverage requests waiting.
     */
    func remaining()  -> UInt64
    
    /**
     * After signing in or when the network is back.
     */
    func resume() 
    
    func setListener(listener: ExplorerListener) 
    
    func state()  -> QueueState
    
    func stats(database: ExplorerDatabase, epd: Epd)  -> ExplorerStats?
    
}
